package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.PreferredUsernameVO;

class PreferredUsernameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of preferred username of user profile")
  void test_preferred_username_value_holder_assign_plain_value() {
    Object holder = new Object();
    PreferredUsernameValueHolder<Object> value = new PreferredUsernameValueHolder<>(holder);
    Assertions.assertSame(holder, value.preferredUsername("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPreferredUsernameValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getPreferredUsername().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.preferredUsernameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPreferredUsernameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPreferredUsername().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of preferred username of user profile")
  void test_preferred_username_value_holder_assign_value_object() {
    Object holder = new Object();
    PreferredUsernameValueHolder<Object> value = new PreferredUsernameValueHolder<>(holder);
    PreferredUsernameVO vo = PreferredUsernameVO.from("one");
    Assertions.assertFalse(value.getPreferredUsernameValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.preferredUsername(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPreferredUsernameValue().orElseThrow());
    Assertions.assertSame(holder, value.preferredUsername(Optional.empty()));
    Assertions.assertFalse(value.getPreferredUsernameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.preferredUsername(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPreferredUsernameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of preferred username of user profile against the original")
  void test_preferred_username_value_holder_read() {
    Object holder = new Object();
    PreferredUsernameValueHolder<Object> value = new PreferredUsernameValueHolder<>(holder);
    PreferredUsernameVO vo = PreferredUsernameVO.from("one");
    PreferredUsernameVO other = PreferredUsernameVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getPreferredUsernameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPreferredUsername(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPreferredUsername(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.preferredUsername(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPreferredUsername(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPreferredUsername(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of preferred username of user profile")
  void test_preferred_username_value_holder_unset() {
    Object holder = new Object();
    PreferredUsernameValueHolder<Object> value = new PreferredUsernameValueHolder<>(holder);
    PreferredUsernameVO vo = PreferredUsernameVO.from("one");
    value.preferredUsername(vo);
    Assertions.assertSame(holder, value.unsetPreferredUsernameIfMatches("preferredUsername_other"));
    Assertions.assertTrue(value.getPreferredUsernameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPreferredUsernameIfMatches("preferredUsername"));
    Assertions.assertFalse(value.getPreferredUsernameValue().isPresent(),
        "The field name must clear the value");
    value.preferredUsername(vo);
    Assertions.assertSame(holder, value.unsetPreferredUsername());
    Assertions.assertFalse(value.getPreferredUsernameValue().isPresent(),
        "Unset must clear the value");
  }
}
